package markdown

import (
	"fmt"
	"strings"
)

// Render translates a markdown document to HTML.
//
// The document is processed line by line:
//   - a line starting with 1-6 '#' characters is a header,
//   - a line starting with '* ' is an unordered list item,
//   - anything else is a paragraph.
//
// Before that, the first bold (__...__) and italic (_..._) pairs in the
// document are converted to <strong> and <em> tags.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var b strings.Builder
	inList := false

	for _, line := range strings.Split(markdown, "\n") {
		if inList && !isListItem(line) {
			b.WriteString("</ul>")
			inList = false
		}
		switch {
		case isHeader(line):
			b.WriteString(renderHeader(line))
		case isListItem(line):
			if !inList {
				b.WriteString("<ul>")
				inList = true
			}
			b.WriteString("<li>" + line[2:] + "</li>")
		default:
			b.WriteString("<p>" + line + "</p>")
		}
	}
	if inList {
		b.WriteString("</ul>")
	}
	return b.String()
}
```

